import{_ as n,l as r,o as e,c as l,v as t,p as s,x as o,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"商品期权与季节性","description":"","frontmatter":{"title":"商品期权与季节性","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/commodity-options-seasonality.md","filePath":"quant/commodity-options-seasonality.md","lastUpdated":1789023840000}'),B={name:"quant/commodity-options-seasonality.md"};function E(p,a,h,A,u,_){const i=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="商品期权与季节性" tabindex="-1">商品期权与季节性 <a class="header-anchor" href="#商品期权与季节性" aria-label="Permalink to &quot;商品期权与季节性&quot;">​</a></h1><div class="epigraph"><p>商品期权写在期货合约上，不是写在一个永久现货 GBM 上；季节性出现在远期曲线的形状与波动的日历里。</p><footer>—— Black, The Pricing of Commodity Contracts, Journal of Financial Economics, 1976；季节性与库存见 Geman, Commodities and Commodity Derivatives</footer></div><p><a href="/quant/xccy-swap-pricing">上一课</a>收口 FX 线性。商品的缺口是<strong>标的是期货曲线</strong>：每个到期一个合约，展期、库存、季节把曲线拧成 contango 或 backwardation。主干 <a href="/quant/contango-backwardation">Contango / Backwardation</a> 与 <a href="/quant/roll-yield">展期收益</a> 已写曲线经济学。本课只写期权：Black-76 在哪个期货上、波动的季节、以及亚式在商品里为何是默认而不是奇异。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用现货 GBM 去估 WTI 期权，会把便利收益、库存与展期胡乱折进 \\(q\\)。正确输入是该期权对应的期货价格 \\(F(t,T)\\) 与该合约的隐波。不同 \\(T\\) 的期货不是同一资产的「更长期限」，相关不满 1，日历价差期权是真正的两资产产品。问题是季节：天然气、电力、农产品的波动在冬季/收获期上升，ATM 期限结构不是单调的股权样微笑期限结构。把 <a href="/quant/sabr">SABR</a> 按股权习惯按 \\(T\\) 光滑插值，会抹掉季节峰。</p><p>商品亚式（月均结算）是场内场外的主流，因为现货与期货在交割月收敛、日结算噪声大。亚式课的算术平均在这里是合约默认。</p><h3 id="波动的对象是期货-不是现货" tabindex="-1">波动的对象是期货，不是现货 <a class="header-anchor" href="#波动的对象是期货-不是现货" aria-label="Permalink to &quot;波动的对象是期货，不是现货&quot;">​</a></h3><p>Samuelson 效应：近月期货波动往往高于远月。期权的 Vega 桶应按合约月份，而不是按「30 天、90 天」的股权网格硬切。近月期权在进入交割与停牌规则前，流动性与跳（库存公布）主导，模型带要加事件情景。</p><p><span class="marginnote">电力与天然气还有日/小时产品，连续 GBM 完全不够，后课天气与电力再写尖峰。本课停在液体期货期权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个期货到期单独的 Black-76 曲面，允许季节性节点。日历价差期权用两期货的相关，相关随到期差增大而下降。亚式用期货路径在结算窗上的平均，注意平均的是哪个合约、是否滚动。对冲用对应月份期货，禁止用远月流动性更好的合约去对冲近月 Gamma 而不记账基差。</p><p>库存与便利收益进入曲线校准，不直接进期权公式；它们通过 \\(F(t,T)\\) 已经在价格里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>期货是可交易的无资金标的，Black-76 的漂移为 0。季节性是确定性的日历调制乘在瞬时 vol 上，或乘在曲线形状上。期权把这两种季节都吃进去：曲线季节改变 Delta（沿曲线的滚动），vol 季节改变 Theta 租金的日历。股权里「周一 Theta」与商品里「二月 vol」不是同一数量级。</p>',14)),(e(),s(m,null,{default:o(()=>[c(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Curve%5B%22%E6%9C%9F%E8%B4%A7%E6%9B%B2%E7%BA%BF%20%E5%AD%A3%E8%8A%82%E4%B8%8E%E5%BA%93%E5%AD%98%22%5D%20--%3E%20F%5B%22%E5%AF%B9%E5%BA%94%E6%9C%88%E4%BB%BD%20F%20t%20T%22%5D%0A%20%20F%20--%3E%20Blk%5B%22Black-76%20%E8%AF%A5%E5%90%88%E7%BA%A6%22%5D%0A%20%20Seas%5B%22%E6%B3%A2%E5%8A%A8%E5%AD%A3%E8%8A%82%E5%B3%B0%22%5D%20--%3E%20Surf%5B%22%E6%8C%89%E6%9C%88%E4%BB%BD%E7%9A%84%E6%9B%B2%E9%9D%A2%22%5D%0A%20%20Surf%20--%3E%20Blk%0A%20%20Blk%20--%3E%20Asian%5B%22%E6%9C%88%E5%9D%87%E4%BA%9A%E5%BC%8F%E6%98%AF%E9%BB%98%E8%AE%A4%E7%BB%93%E7%AE%97%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交割量、仓单、逼仓使近月价格可以脱离扩散。模型若无跳与库存约束，会低估虚值看涨。碳排放、航运等「商品」流动性与电力不同，不要共用天然气季节模板。FX 计价的商品还有 quanto 与运费。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>商品期权标的是期货合约；Black-76 按月份，不要用现货 GBM。</li><li>季节性出现在曲线与 vol 日历上，插值不能抹平。</li><li>亚式月均是主流结算；日历价差是两资产相关产品。</li><li>出处：Black, <em>JFE</em>, 1976；Geman, <em>Commodities and Commodity Derivatives</em>。</li></ul>',4))])}const k=n(B,[["render",E]]);export{T as __pageData,k as default};
